package frameworks

import "embed"

// embedded holds every controls.json shipped with this SDK build.
//
// # Description
//
// The single glob picks up every dated version directory under every
// framework_id directory; new seeds (CV-11 through CV-18) require zero
// changes to this directive once their controls.json is generated by
// cmd/frameworks-seedgen.
//
// Embedded files are bytes-on-disk: regenerating a seed file by
// running `go run ./cmd/frameworks-seedgen <id>` updates this embed
// at the next build. Once a version directory has shipped to a
// customer in a bundle, it is immutable (epic lock 5); the regenerator
// would simply emit byte-identical output.
//
//go:embed all:*/v_*/controls.json
var embedded embed.FS
